CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','SALES_MANAGER','SALES_REP','VIEWER');
CREATE TYPE "QuoteStatus" AS ENUM ('DRAFT','INTERNAL_REVIEW','SENT','VIEWED','ACCEPTED','REJECTED','EXPIRED');
CREATE TYPE "RFQStatus" AS ENUM ('NEW','REVIEWING','PRICING','QUOTED','WON','LOST','EXPIRED','CANCELLED');
CREATE TYPE "FollowUpStatus" AS ENUM ('PENDING','COMPLETED','SNOOZED');
CREATE TYPE "CatalogType" AS ENUM ('PRODUCT','SERVICE','LABOR','MATERIAL','PACKAGE');
CREATE TYPE "IntegrationKind" AS ENUM ('AI','EMAIL','STORAGE','BILLING');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"emailVerifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"reportingCurrency" TEXT NOT NULL DEFAULT 'AED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "Membership" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"role" "Role" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Membership_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "Membership_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,UNIQUE("userId","organizationId"));
CREATE TABLE "CompanySettings" ("organizationId" TEXT PRIMARY KEY,"data" JSONB NOT NULL,"marginMode" TEXT NOT NULL DEFAULT 'WARNING',"minMargin" DECIMAL(7,4) NOT NULL DEFAULT 20,"quoteValidityDays" INTEGER NOT NULL DEFAULT 30,"quoteCounter" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "CompanySettings_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE TABLE "Customer" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"companyName" TEXT NOT NULL,"contactName" TEXT,"email" TEXT,"phone" TEXT,"whatsapp" TEXT,"address" TEXT,"country" TEXT,"industry" TEXT,"taxNumber" TEXT,"notes" TEXT,"assignedUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "Customer_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE TABLE "CatalogItem" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"sku" TEXT,"name" TEXT NOT NULL,"description" TEXT,"category" TEXT,"brand" TEXT,"type" "CatalogType" NOT NULL DEFAULT 'PRODUCT',"unit" TEXT NOT NULL DEFAULT 'each',"cost" DECIMAL(16,4) NOT NULL,"sellingPrice" DECIMAL(16,4) NOT NULL,"minimumPrice" DECIMAL(16,4),"taxRate" DECIMAL(7,4) NOT NULL DEFAULT 0,"currency" TEXT NOT NULL,"leadTimeDays" INTEGER,"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "CatalogItem_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,UNIQUE("organizationId","sku"));
CREATE TABLE "RFQ" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"number" TEXT NOT NULL,"title" TEXT NOT NULL,"customerId" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deadline" TIMESTAMP(3),"priority" TEXT NOT NULL DEFAULT 'Normal',"status" "RFQStatus" NOT NULL DEFAULT 'NEW',"source" TEXT,"notes" TEXT,"assignedUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "RFQ_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,CONSTRAINT "RFQ_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT,UNIQUE("organizationId","number"));
CREATE TABLE "RFQItem" ("id" TEXT PRIMARY KEY,"rfqId" TEXT NOT NULL,"description" TEXT NOT NULL,"quantity" DECIMAL(16,4) NOT NULL,"unit" TEXT,"notes" TEXT,"sourceText" TEXT,"confidence" DECIMAL(5,4),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RFQItem_rfqId_fkey" FOREIGN KEY("rfqId") REFERENCES "RFQ"("id") ON DELETE CASCADE);
CREATE TABLE "Quote" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"number" TEXT NOT NULL,"customerId" TEXT NOT NULL,"rfqId" TEXT,"title" TEXT NOT NULL,"status" "QuoteStatus" NOT NULL DEFAULT 'DRAFT',"currency" TEXT NOT NULL,"issueDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiryDate" TIMESTAMP(3),"discount" DECIMAL(16,4) NOT NULL DEFAULT 0,"paymentTerms" TEXT,"deliveryTerms" TEXT,"customerNotes" TEXT,"internalNotes" TEXT,"publicTokenHash" TEXT UNIQUE,"publicTokenExpiresAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 1,"snapshot" JSONB,"sentAt" TIMESTAMP(3),"viewedAt" TIMESTAMP(3),"acceptedAt" TIMESTAMP(3),"rejectedAt" TIMESTAMP(3),"rejectionReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "Quote_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,CONSTRAINT "Quote_customerId_fkey" FOREIGN KEY("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT,CONSTRAINT "Quote_rfqId_fkey" FOREIGN KEY("rfqId") REFERENCES "RFQ"("id") ON DELETE SET NULL,UNIQUE("organizationId","number"));
CREATE TABLE "QuoteItem" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL,"catalogItemId" TEXT,"nameSnapshot" TEXT NOT NULL,"skuSnapshot" TEXT,"descriptionSnapshot" TEXT,"quantity" DECIMAL(16,4) NOT NULL,"unitSnapshot" TEXT NOT NULL,"costSnapshot" DECIMAL(16,4) NOT NULL,"sellingPrice" DECIMAL(16,4) NOT NULL,"taxRate" DECIMAL(7,4) NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "QuoteItem_quoteId_fkey" FOREIGN KEY("quoteId") REFERENCES "Quote"("id") ON DELETE CASCADE);
CREATE TABLE "QuoteEvent" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL,"type" TEXT NOT NULL,"actorUserId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuoteEvent_quoteId_fkey" FOREIGN KEY("quoteId") REFERENCES "Quote"("id") ON DELETE CASCADE);
CREATE TABLE "QuoteAcceptance" ("id" TEXT PRIMARY KEY,"quoteId" TEXT NOT NULL UNIQUE,"quoteVersion" INTEGER NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"statement" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuoteAcceptance_quoteId_fkey" FOREIGN KEY("quoteId") REFERENCES "Quote"("id") ON DELETE CASCADE);
CREATE TABLE "FollowUp" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"quoteId" TEXT NOT NULL,"task" TEXT NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"status" "FollowUpStatus" NOT NULL DEFAULT 'PENDING',"notes" TEXT,"assignedUserId" TEXT,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "FollowUp_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,CONSTRAINT "FollowUp_quoteId_fkey" FOREIGN KEY("quoteId") REFERENCES "Quote"("id") ON DELETE CASCADE,CONSTRAINT "FollowUp_assignedUserId_fkey" FOREIGN KEY("assignedUserId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE TABLE "Attachment" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"byteSize" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMP(3),CONSTRAINT "Attachment_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE TABLE "Subscription" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL UNIQUE,"plan" TEXT NOT NULL DEFAULT 'FREE',"status" TEXT NOT NULL DEFAULT 'INACTIVE',"stripeCustomerId" TEXT UNIQUE,"stripeSubscriptionId" TEXT UNIQUE,"currentPeriodEnd" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Subscription_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE TABLE "Integration" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"kind" "IntegrationKind" NOT NULL,"provider" TEXT NOT NULL,"encryptedConfig" BYTEA,"enabled" BOOLEAN NOT NULL DEFAULT FALSE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Integration_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,UNIQUE("organizationId","kind"));
CREATE TABLE "AIUsage" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"provider" TEXT NOT NULL,"feature" TEXT NOT NULL,"inputTokens" INTEGER NOT NULL DEFAULT 0,"outputTokens" INTEGER NOT NULL DEFAULT 0,"success" BOOLEAN NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AIUsage_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"actorUserId" TEXT,"action" TEXT NOT NULL,"objectType" TEXT NOT NULL,"objectId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_organizationId_fkey" FOREIGN KEY("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE,CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Quote_publicTokenHash_expiry_idx" ON "Quote"("publicTokenHash","publicTokenExpiresAt"); CREATE INDEX "Attachment_org_created_idx" ON "Attachment"("organizationId","createdAt"); CREATE INDEX "RFQItem_rfq_idx" ON "RFQItem"("rfqId"); CREATE INDEX "PasswordResetToken_user_expiry_idx" ON "PasswordResetToken"("userId","expiresAt");
CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId","expiresAt"); CREATE INDEX "Membership_organizationId_role_idx" ON "Membership"("organizationId","role"); CREATE INDEX "Customer_organizationId_companyName_idx" ON "Customer"("organizationId","companyName"); CREATE INDEX "CatalogItem_organizationId_name_idx" ON "CatalogItem"("organizationId","name"); CREATE INDEX "RFQ_organizationId_status_deadline_idx" ON "RFQ"("organizationId","status","deadline"); CREATE INDEX "Quote_organizationId_status_issueDate_idx" ON "Quote"("organizationId","status","issueDate"); CREATE INDEX "Quote_organizationId_customerId_idx" ON "Quote"("organizationId","customerId"); CREATE INDEX "QuoteItem_quoteId_sortOrder_idx" ON "QuoteItem"("quoteId","sortOrder"); CREATE INDEX "QuoteEvent_quoteId_createdAt_idx" ON "QuoteEvent"("quoteId","createdAt"); CREATE INDEX "FollowUp_organizationId_status_dueAt_idx" ON "FollowUp"("organizationId","status","dueAt"); CREATE INDEX "AuditLog_organizationId_createdAt_idx" ON "AuditLog"("organizationId","createdAt"); CREATE INDEX "AIUsage_organizationId_createdAt_idx" ON "AIUsage"("organizationId","createdAt");
